package cn.zhuatech.enterprisesearch.deep;import cn.zhuatech.enterprisesearch.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/search-ops") public class DeepDomainController{private final DeepDomainService s;public DeepDomainController(DeepDomainService s){this.s=s;}@GetMapping("/dashboard")ApiResponse<?> dashboard(@RequestParam String organizationCode){return ApiResponse.ok(s.dashboard(organizationCode));}@PostMapping("/sources")ApiResponse<?> source(@Valid @RequestBody DeepDomainService.SourceRequest r){return ApiResponse.ok(s.source(r));}@PostMapping("/sources/{id}/documents")ApiResponse<?> index(@PathVariable Long id,@Valid @RequestBody DeepDomainService.DocumentRequest r){return ApiResponse.ok(s.index(id,r));}@PostMapping("/search")ApiResponse<?> search(@Valid @RequestBody DeepDomainService.SearchRequest r){return ApiResponse.ok(s.search(r));}@PostMapping("/feedback")ApiResponse<?> feedback(@Valid @RequestBody DeepDomainService.FeedbackRequest r){return ApiResponse.ok(s.feedback(r));}}
